import { motion } from "framer-motion";

export default function Home() {
  return (
    <motion.div
      className="flex flex-col items-center justify-center min-h-screen text-center bg-gradient-to-b from-indigo-50 to-white"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.6 }}
    >
      <h1 className="text-5xl font-bold text-indigo-700 mb-4">AI Interview Coach</h1>
      <p className="text-gray-600 text-lg max-w-xl">
        Prepare smarter with AI — get personalized feedback and improve your interview confidence.
      </p>
      <button className="mt-8 px-6 py-3 bg-indigo-600 text-white rounded-xl shadow-md hover:bg-indigo-700 transition-all">
        Get Started
      </button>
    </motion.div>
  );
}
